using System;
using System.IO;
using System.Collections.Generic;
using Ashfall.Modules.Avatar;
class AvatarR4Tests
{
 static int count;static void Check(bool b,string n){if(!b)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}static void Reject(Action a,string n){try{a();}catch(AvatarValidationException){Check(true,n);return;}throw new Exception("Accepted "+n);}
 static float Motion(float[] a,float[] b){float max=0;for(int i=0;i<a.Length;i++)max=Math.Max(max,Math.Abs(a[i]-b[i]));return max;}
 static void Main(){var assembly=AvatarR4Fixtures.Assembly();Check(assembly.CopyParts().Length==16,"composed real hands and analytic14 body parts");
 foreach(var part in assembly.CopyParts()){if(part.Label!="LeftHand"&&part.Label!="RightHand"){Check(VerifiedMeshReader.Read(part).CopyVertices().Length==9,"actual rigid decode "+part.Label);continue;}
 var s=VerifiedSkinReader.Read(part);string side=part.Label=="LeftHand"?"left":"right";var provider=AvatarR4Fixtures.Grip(s,side);var mount=SourceGripMount.Create(s,side=="left");Check(AvatarMath.ValidTrs(mount)&&Math.Abs(mount[4])==1,side+" actual source palm/quarterturn mount");var rest=s.Deform(s.CopyLocalMatrices());var opened=provider.Update(0,0,"free","free","",1);var open=s.Deform(opened.CopyLocalMatrices());var closed=provider.Update(1,1,"free","free","",1);Check(Motion(open,s.Deform(closed.CopyLocalMatrices()))>.001f,side+" authored open/closed motion");var held=provider.Update(0,0,"held","sword","sword",1);Check(Motion(rest,s.Deform(held.CopyLocalMatrices()))>.001f,side+" authored nonidentity held sword");using(var reader=new BinaryReader(File.OpenRead(side=="left"?"L-source-grip-oracle.bin":"R-source-grip-oracle.bin"))){int n=reader.ReadInt32();var matrices=held.CopyLocalMatrices();for(int j=0;j<n;j++){int node=reader.ReadInt32();var expected=new float[16];for(int k=0;k<16;k++)expected[k]=reader.ReadSingle();Check(Motion(expected,matrices[node])<.000002f,side+" independent source quaternion/SRS oracle node"+node);}}var copy=held.CopyLocalMatrices();copy[27]=null;Check(held.CopyLocalMatrices()[27]!=null,side+" snapshot isolated");Reject(()=>new FrozenSkinPose(s,copy),side+" typed null ancestor");
 var p2=AvatarR4Fixtures.Grip(s,side);var before=p2.Update(0,0,"free","free","",0);var after=p2.Update(1,1,"held","sword","sword",0);Check(Motion(s.Deform(before.CopyLocalMatrices()),s.Deform(after.CopyLocalMatrices()))==0,side+" zero delta frozen");Reject(()=>p2.Update(float.NaN,0,"free","free","",1),side+" invalid frame");Check(Motion(s.Deform(after.CopyLocalMatrices()),s.Deform(p2.Update(1,1,"free","free","",0).CopyLocalMatrices()))==0,side+" rejection preserves state");
 foreach(string id in new[]{"matadors","magnum","tec9","knife","px4","1911","mp9","other"}){var pose=provider.Update(0,0,"held","free",id,.02f);Check(s.Deform(pose.CopyLocalMatrices()).Length==2436,side+" real held "+id);}
 }
 Check(SourceGripPose.Closure("matadors","free",false,0)==1.05f&&SourceGripPose.Closure("matadors","sword",true,1)==.80f,"matadors priority and extrapolation");Check(SourceGripPose.Closure("px4","sword",false,0)==1.12f,"sword priority");
 var material=AvatarR4Fixtures.Material(assembly);material.Require(assembly,assembly.CopyParts()[14]);Check(!material.Approved&&material.CopyAlbedo().Length>100000,"actual source camo material admitted only pilot");var bytes=material.CopyOrm();bytes[0]=0;Check(material.CopyOrm()[0]==137,"immutable ORM");Reject(()=>new HandMaterialReceipt(assembly,"default",AvatarR4Fixtures.Asset("glove_camo_albedo.png"),AvatarR4Fixtures.Asset("glove_camo_orm.png"),AvatarR4Fixtures.Asset("glove_camo_normal.png"),"forged",null,AvatarUse.Production),"real reference cannot approve material");
 var receipts=AvatarR4Fixtures.Receipts(assembly);Check(receipts.Material(assembly,assembly.CopyParts()[14])!=null,"receipt assembly path");var badPart=new PreparedPart(new PartRecord{MaterialSlots="changed",Mount=SkinMatrix.Identity()},assembly.CopyParts()[14].Asset);Reject(()=>material.Require(assembly,badPart),"material slot substitution");
 byte[] badJson=System.Text.Encoding.UTF8.GetBytes("{\"asset\":{\"version\":[]}}");var malformed=new PreparedPart(new PartRecord{Node="mesh",MaterialSlots="default",Mount=SkinMatrix.Identity()},new VerifiedAsset(new AssetRecord{Sha256=ManifestXml.Sha(badJson)},badJson));Reject(()=>VerifiedSkinReader.Read(malformed),"typed malformed version array");
 var dep=new ReceiptSkinDependencies(File.ReadAllText("external.closure"),new Dictionary<string,VerifiedAsset>{{"rig.bin",AvatarR4Fixtures.Asset("rig.bin")}});var ep=new PreparedPart(new PartRecord{Node="mesh",MaterialSlots="default",Mount=SkinMatrix.Identity()},AvatarR4Fixtures.Asset("external.gltf"));Check(VerifiedSkinReader.Read(ep,dep).CopyVertices().Length==9,"real receipt dependency provider");Reject(()=>dep.Resolve("unknown"),"unknown dependency fails closed");
 string huge=Path.GetFullPath("oversize.bin");using(var f=File.Create(huge))f.SetLength(VerifiedSkinReader.MaxBytes+1L);Reject(()=>new FileAvatarAssets().Read(huge),"initial file bound before allocation");File.Delete(huge);
 AvatarR4Fixtures.Source src;var m=AvatarR4Fixtures.Manifest(out src);m.Parts[0].Mount=new float[100000];Reject(()=>AvatarAssembler.Prepare(m,src,null,AvatarUse.UnreviewedPilot),"manifest nested array before serialization");
 m=AvatarR4Fixtures.Manifest(out src);var large=new byte[VerifiedSkinReader.MaxBytes];foreach(var a in m.Assets){src.Bytes[a.AbsolutePath]=large;a.Sha256=ManifestXml.Sha(large);}Reject(()=>AvatarAssembler.Prepare(m,src,null,AvatarUse.UnreviewedPilot),"assembly aggregate admission");
 byte[] registry=File.ReadAllBytes("consumed/game/scripts/gemini_player_models_099.gd");string registryHash=ManifestXml.Sha(registry);var profile=SourceBodyProfile.Game(registry,registryHash,"camo");profile.Require(assembly);Check(profile.EyeToShoulder==.29f&&profile.BodyRear==.12f,"source camo profile admission");var pj=SourceBodyProfile.Game(registry,registryHash,"pj");Check(pj.EyeToShoulder==.18f&&pj.BodyRear==.06f,"actual game PJ profile");var blair=SourceBodyProfile.Game(registry,registryHash,"blair_pumpkin_spice");Check(blair.EyeToShoulder==.21f&&blair.BodyRear==0&&blair.ChestPlateFollowsJacket,"actual game Blair profile");Reject(()=>pj.Require(assembly),"profile substitution");var quest=SourceBodyProfile.QuestFixed("pj",ManifestXml.Sha(File.ReadAllBytes("consumed/quest-r22/source/scripts/player_body.gd")));Check(quest.EyeToShoulder==.29f&&quest.BodyRear==.12f&&!quest.ChestPlateFollowsJacket,"Quest separately pinned fixed profile");
 Console.WriteLine("RESULT "+count+" r4 checks; real Editor/API/visual UNKNOWN");}
